(7514627, 1199801, 65234, '<td valign="top">Phenomenal image! I pity the people on that plane ... and yours, as well.</td>', 'Phenomenal image! I pity the people on that plane ... and yours, as well.', '2017-05-19 08:29:01.000000', NULL, 1),
(7514628, 1200133, 65234, '<td valign="top">Perfect depiction of bad weather and its effects.</td>', 'Perfect depiction of bad weather and its effects.', '2017-05-19 08:29:37.000000', NULL, 1),
(7514629, 1200103, 65234, '<td valign="top">Stunning image. It''s amazing how varied the weather is in this scene. From crummy rain to blue skies.</td>', 'Stunning image. It''s amazing how varied the weather is in this scene. From crummy rain to blue skies.', '2017-05-19 08:30:26.000000', NULL, 1),
(7514630, 1200157, 65234, '<td valign="top">Hard to beat lightning for a great image of bad weather. Lovely colors in the sky.</td>', 'Hard to beat lightning for a great image of bad weather. Lovely colors in the sky.', '2017-05-19 08:30:52.000000', NULL, 1),
(7514631, 1200147, 65234, '<td valign="top">I always feel sorry for the wildlife in a snowstorm. Nice image. I particularly like the little bits of snow kicked up by her feet.</td>', 'I always feel sorry for the wildlife in a snowstorm. Nice image. I particularly like the little bits of snow kicked up by her feet.', '2017-05-19 08:33:36.000000', NULL, 1),
(7514632, 1199614, 65234, '<td valign="top">Poor fellow :-(  Nicely emotive image.</td>', 'Poor fellow :-(  Nicely emotive image.', '2017-05-19 08:34:00.000000', NULL, 1),
(7514633, 1200160, 65234, '<td valign="top">Very ominous sky. Kind of want the water a little lighter so I can see the turbulence better. It''s very dark on my screen.</td>', 'Very ominous sky. Kind of want the water a little lighter so I can see the turbulence better. It''s very dark on my screen.', '2017-05-19 08:36:52.000000', NULL, 1),
(7514634, 1199950, 65234, '<td valign="top">Interesting subject and nicely ominous clouds.</td>', 'Interesting subject and nicely ominous clouds.', '2017-05-19 08:37:19.000000', NULL, 1),
(7514635, 1200015, 65234, '<td valign="top">Bonus point for your title :-) The scene looks positively miserable!</td>', 'Bonus point for your title :-) The scene looks positively miserable!', '2017-05-19 08:37:47.000000', NULL, 1),
(7514636, 1200146, 65234, '<td valign="top">Nice! I love how water on a windshield can create beautifully distorted abstracts.</td>', 'Nice! I love how water on a windshield can create beautifully distorted abstracts.', '2017-05-19 08:38:27.000000', NULL, 1),
(7514637, 1200150, 65234, '<td valign="top">I pity the spider.</td>', 'I pity the spider.', '2017-05-19 08:38:38.000000', NULL, 1),
(7514638, 1200137, 65234, '<td valign="top">Nice action shot, of the rabbit and the rain.</td>', 'Nice action shot, of the rabbit and the rain.', '2017-05-19 08:39:12.000000', NULL, 1),
(7514640, 1199887, 65234, '<td valign="top">I like the B&amp;W for this image. Gray and cloudy.</td>', 'I like the B&W for this image. Gray and cloudy.', '2017-05-19 08:39:46.000000', NULL, 1),
(7514641, 1200114, 65234, '<td valign="top">I don''t mind fog as a weather phenomenon but the image is beautiful.</td>', 'I don''t mind fog as a weather phenomenon but the image is beautiful.', '2017-05-19 08:40:41.000000', NULL, 1),
(7514642, 1199934, 65234, '<td valign="top">The droopiness says it''s been raining for quite awhile. Nice image.</td>', 'The droopiness says it''s been raining for quite awhile. Nice image.', '2017-05-19 08:41:17.000000', NULL, 1),
(7514643, 1199582, 65234, '<td valign="top">Is that a person in a costume? It''s so random!! I actually noticed that before I saw the flooding. Not sure if that''s the best thing for this challenge, but this is a good depiction of a flood.</td>', 'Is that a person in a costume? It''s so random!! I actually noticed that before I saw the flooding. Not sure if that''s the best thing for this challenge, but this is a good depiction of a flood.', '2017-05-19 08:42:30.000000', NULL, 1),
(7514644, 1199905, 65234, '<td valign="top">Nice abstract! Rain on a windshield makes for interesting images.</td>', 'Nice abstract! Rain on a windshield makes for interesting images.', '2017-05-19 08:42:57.000000', NULL, 1),
